const $=id=>document.getElementById(id),audio=$('audio'),canvas=$('game'),ctx=canvas.getContext('2d');
const originalChart=await fetch('chart.json').then(r=>{if(!r.ok)throw Error('Chart unavailable');return r.json()});
let chart=structuredClone(originalChart);
const preview='https://audio-ssl.itunes.apple.com/itunes-assets/AudioPreview221/v4/62/ff/3a/62ff3abe-bc6d-a7d0-31b0-71cbec9aaa24/mzaf_13802296211720217737.plus.aac.p.m4a';
audio.src=preview;let notes=[],state='select',score=0,combo=0,maxCombo=0,hits=0,judged=0,pressed=[false,false,false,false],judgeUntil=0,flashes=[0,0,0,0],particles=[],generation=0,counts={perfect:0,great:0,ok:0,miss:0},emptyPresses=0,blob=null,sfxEnabled=true,soundContext=null;
let duration=chart.duration;const travel=1.8,buttons=[...document.querySelectorAll('[data-lane]')];
function setState(next){state=next;document.body.dataset.state=next;$('selection').hidden=!['select','loading'].includes(next);$('pausePanel').hidden=next!=='paused';$('result').hidden=next!=='result';$('pause').disabled=!['playing','paused'].includes(next);$('pause').textContent=next==='paused'?'▶':'Ⅱ';$('headerTitle').textContent=next==='select'?'经典四键':next==='result'?'演奏成绩':'正在演奏'}
function sound(kind){if(!sfxEnabled||!soundContext)return;const now=soundContext.currentTime;const seq=kind==='end'?[523,659,784,1047]:kind==='go'?[784,1047]:[kind==='confirm'?660:440];seq.forEach((freq,i)=>{const osc=soundContext.createOscillator(),gain=soundContext.createGain();osc.type='sine';osc.frequency.value=freq;gain.gain.setValueAtTime(.0001,now+i*.09);gain.gain.exponentialRampToValueAtTime(.045,now+i*.09+.01);gain.gain.exponentialRampToValueAtTime(.0001,now+i*.09+.16);osc.connect(gain);gain.connect(soundContext.destination);osc.start(now+i*.09);osc.stop(now+i*.09+.18)})}
function release(lane){pressed[lane]=false;buttons[lane].classList.remove('active')}
function reset(){audio.pause();audio.currentTime=0;notes=chart.notes.map(n=>({...n,state:0}));score=combo=maxCombo=hits=judged=emptyPresses=0;counts={perfect:0,great:0,ok:0,miss:0};flashes=[0,0,0,0];particles=[];pressed.forEach((_,i)=>release(i));$('judge').textContent='';$('countdown').textContent='';$('selection').classList.remove('leaving');$('start').disabled=false;update()}
function update(){$('score').textContent=String(score).padStart(6,'0');$('bigCombo').textContent=combo;$('stageCombo').style.opacity=state==='playing'&&combo>=2?'1':'0';$('life').style.width=(judged?Math.max(12,hits/judged*100):100)+'%';$('noteCount').textContent=notes.length+' NOTES'}
function feedback(text,color){$('judge').textContent=text;$('judge').style.color=color;judgeUntil=performance.now()+420;$('judge').animate([{transform:'translateY(6px) scale(1.25)',opacity:.6},{transform:'translateY(0) scale(1)',opacity:1}],{duration:140})}
function hit(lane){if(state!=='playing'||audio.paused||pressed[lane])return;pressed[lane]=true;buttons[lane].classList.add('active');const now=audio.currentTime+Number($('offset').value)/1000;const n=notes.find(n=>!n.state&&n.lane===lane&&Math.abs(n.time-now)<=.18);if(!n){combo=0;emptyPresses++;update();return}n.state=1;judged++;flashes[lane]=performance.now();for(let i=0;i<18;i++)particles.push({lane,age:0,vx:(Math.random()-.5)*130,vy:-35-Math.random()*180,x:0,y:0});const delta=Math.abs(n.time-now);if(delta<=.055){score+=1000;hits++;counts.perfect++;feedback('PERFECT','#ffe49b')}else if(delta<=.110){score+=700;hits+=.7;counts.great++;feedback('GREAT','#94edff')}else{score+=300;hits+=.3;counts.ok++;feedback('GOOD','#d9c0fa')}combo++;maxCombo=Math.max(maxCombo,combo);update()}
const wait=ms=>new Promise(r=>setTimeout(r,ms));
async function start(){if(state==='loading'||state==='countdown')return;const id=++generation;reset();$('config').close();setState('loading');$('start').disabled=true;$('status').textContent='正在加载音乐…';$('countdown').textContent='';try{soundContext??=new(window.AudioContext||window.webkitAudioContext)();await soundContext.resume();sound('confirm');audio.volume=0;await audio.play();if(id!==generation){audio.pause();audio.volume=1;return}audio.pause();audio.currentTime=0;audio.volume=1;$('selection').classList.add('leaving');await wait(300);if(id!==generation)return;setState('countdown');$('status').textContent='手指放在 D F J K 上';for(const word of ['READY','GO!']){if(id!==generation)return;$('countdown').textContent=word;$('countdown').classList.remove('pop');void $('countdown').offsetWidth;$('countdown').classList.add('pop');sound(word==='GO!'?'go':'ready');await wait(word==='READY'?800:400)}if(id!==generation)return;await audio.play();if(id!==generation){audio.pause();return}setState('playing');$('countdown').textContent='';$('status').textContent='DFJK 击打 · 空格暂停';update()}catch{if(id!==generation)return;audio.pause();audio.volume=1;setState('select');$('countdown').textContent='';$('status').textContent='音频加载失败，请重试或在设置中加载个人音频';$('start').disabled=false}}
function toSelect(){generation++;audio.pause();audio.volume=1;reset();setState('select');$('status').textContent='戴上耳机，准备开始';update()}
function pause(){if(state!=='playing')return;audio.pause();pressed.forEach((_,i)=>release(i));setState('paused');$('status').textContent='已暂停';$('judge').textContent='';update()}
async function resume(){if(state!=='paused')return;const id=generation;try{await audio.play();if(id!==generation){audio.pause();return}setState('playing');$('status').textContent='DFJK 击打 · 空格暂停';update()}catch{$('status').textContent='无法继续播放，请重试'}}
function end(){if(state==='result')return;generation++;audio.pause();for(const n of notes)if(!n.state){n.state=-1;judged++;counts.miss++;combo=0}setState('result');update();$('judge').textContent='';const accuracy=hits/Math.max(1,notes.length);$('accuracy').textContent=(accuracy*100).toFixed(1)+'%';$('maxCombo').textContent=maxCombo;$('rank').textContent=accuracy>=.95?'S':accuracy>=.85?'A':accuracy>=.7?'B':'C';$('fullCombo').hidden=!(notes.length>0&&maxCombo===notes.length&&emptyPresses===0);$('breakdown').textContent='PERFECT '+counts.perfect+' · GREAT '+counts.great+' · GOOD '+counts.ok+' · MISS '+counts.miss;$('result').querySelector('h2').textContent=chart.title;$('resultArtist').textContent=chart.artist||'PERSONAL AUDIO';$('status').textContent='演奏完成 · 再来一局？';sound('end');const target=score,id=generation,t0=performance.now();function roll(t){if(id!==generation)return;$('resultScore').textContent=String(Math.round(target*Math.min(1,(t-t0)/600))).padStart(6,'0');if(t-t0<600)requestAnimationFrame(roll)}requestAnimationFrame(roll)}
$('start').onclick=start;$('again').onclick=start;$('restart').onclick=start;$('resume').onclick=resume;$('pause').onclick=()=>state==='playing'?pause():resume();['back','return','resultBack'].forEach(id=>$(id).onclick=toSelect);
$('settings').onclick=()=>{if(state==='playing')pause();else if(['loading','countdown'].includes(state))toSelect();$('config').showModal()};
$('sound').onclick=()=>{sfxEnabled=!sfxEnabled;$('sound').textContent=sfxEnabled?'♪':'♩';$('sound').setAttribute('aria-pressed',String(sfxEnabled))};
audio.addEventListener('waiting',()=>{if(state==='playing')$('status').textContent='音乐缓冲中…'});audio.addEventListener('playing',()=>{if(state==='playing')$('status').textContent='DFJK 击打 · 空格暂停'});audio.addEventListener('ended',end);audio.addEventListener('error',()=>{if(state==='playing'){pause();$('status').textContent='音频中断，请重试或切换个人音频'}});
function loseFocus(){pressed.forEach((_,i)=>release(i));if(state==='playing')pause();else if(['countdown','loading'].includes(state))toSelect()}
document.addEventListener('visibilitychange',()=>{if(document.hidden)loseFocus()});window.addEventListener('blur',loseFocus);
window.addEventListener('keydown',e=>{if($('config').open||['INPUT','TEXTAREA'].includes(e.target.tagName)||e.target.isContentEditable)return;if(e.code==='Space'){e.preventDefault();if(!e.repeat){if(state==='playing')pause();else if(state==='paused')resume()}return}const lane=['KeyD','KeyF','KeyJ','KeyK'].indexOf(e.code);if(lane<0||e.repeat)return;e.preventDefault();hit(lane)});window.addEventListener('keyup',e=>{const lane=['KeyD','KeyF','KeyJ','KeyK'].indexOf(e.code);if(lane>=0)release(lane)});buttons.forEach((b,i)=>{b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);hit(i)};b.onpointerup=b.onpointercancel=()=>release(i)});
$('offset').oninput=()=>{$('offsetValue').value=$('offset').value+' ms'};
$('file').onchange=()=>{const f=$('file').files[0];if(!f)return;toSelect();if(blob)URL.revokeObjectURL(blob);blob=URL.createObjectURL(f);audio.src=blob;audio.onloadedmetadata=()=>{if(!Number.isFinite(audio.duration)||audio.duration<3){$('status').textContent='请选择长度至少 3 秒的音频';return}duration=audio.duration;chart={...originalChart,title:f.name,artist:'个人音频',duration,notes:[]};const beat=60/113;for(let i=0;2+i*beat<duration-.7;i++){chart.notes.push({time:2+i*beat,lane:[0,1,3,2,1,0,2,3][i%8]});if(i%8===6)chart.notes.push({time:2+(i+.5)*beat,lane:[1,2,0,3][i%4]})}$('sourceLabel').textContent='个人音频 · 113 BPM 自动练习谱';$('songTitle').textContent=f.name;$('selection').querySelector('h1').textContent=f.name;toSelect();$('status').textContent='个人音频已就绪 · 自动练习谱'}};
$('default').onclick=()=>location.reload();
function clock(t){return Math.floor(t/60)+':'+String(Math.floor(t%60)).padStart(2,'0')}
let lastFrame=performance.now();
function frame(){
 const rect=canvas.getBoundingClientRect(),dpr=devicePixelRatio||1;
 if(canvas.width!==Math.round(rect.width*dpr)||canvas.height!==Math.round(rect.height*dpr)){canvas.width=Math.round(rect.width*dpr);canvas.height=Math.round(rect.height*dpr)}
 ctx.setTransform(dpr,0,0,dpr,0,0);
 const w=rect.width,h=rect.height,line=h-88,now=audio.currentTime,stamp=performance.now(),beat=60/chart.bpm;const dt=Math.min(.05,(stamp-lastFrame)/1000);lastFrame=stamp;
 ctx.clearRect(0,0,w,h);
 const x=(boundary,y)=>w/2+(boundary/4-.5)*w*(.63+.37*Math.min(1,Math.max(0,y/line)));
 function quad(l,r,y1,y2){ctx.beginPath();ctx.moveTo(x(l,y1),y1);ctx.lineTo(x(r,y1),y1);ctx.lineTo(x(r,y2),y2);ctx.lineTo(x(l,y2),y2);ctx.closePath()}
 for(let i=0;i<4;i++){
  const grad=ctx.createLinearGradient(0,0,0,line);grad.addColorStop(0,i%2?'#13244c55':'#18234b55');grad.addColorStop(1,i%2?'#2058a333':'#123c8133');ctx.fillStyle=grad;quad(i,i+1,0,line);ctx.fill();
  const age=(stamp-flashes[i])/350;
  if(pressed[i]||age<1){const glow=ctx.createLinearGradient(0,line-220,0,line);glow.addColorStop(0,'#4dcfff00');glow.addColorStop(1,'#58d8ff'+Math.round((pressed[i]?.45:.5*(1-age))*255).toString(16).padStart(2,'0'));ctx.fillStyle=glow;quad(i,i+1,line-220,line);ctx.fill()}
 }
 for(let i=0;i<=4;i++){ctx.strokeStyle=i===0||i===4?'#659fff99':'#4a78c555';ctx.lineWidth=i===0||i===4?2:1;ctx.beginPath();ctx.moveTo(x(i,0),0);ctx.lineTo(x(i,line),line);ctx.stroke()}
 const first=Math.floor((now-chart.beat_phase)/beat);
 for(let n=first;n<first+8;n++){const time=chart.beat_phase+n*beat,y=line-(time-now)/travel*line;if(y<0||y>line)continue;ctx.strokeStyle=n%4===0?'#7caaff35':'#7caaff13';ctx.lineWidth=n%4===0?2:1;ctx.beginPath();ctx.moveTo(x(0,y),y);ctx.lineTo(x(4,y),y);ctx.stroke()}
 if(state==='playing'&&!audio.paused){for(const n of notes){if(!n.state&&now+Number($('offset').value)/1000-n.time>.18){n.state=-1;combo=0;judged++;counts.miss++;feedback('MISS','#ef90b6');update()}}}
 for(const n of notes){if(n.state)continue;const y=line-(n.time-now)/travel*line;if(y< -20||y>line+35)continue;const thick=11+5*y/line,left=x(n.lane,y)+8,right=x(n.lane+1,y)-8;
  const gradient=ctx.createLinearGradient(0,y-thick,0,y+thick);gradient.addColorStop(0,'#e1faff');gradient.addColorStop(.25,'#72daff');gradient.addColorStop(1,'#176cc8');ctx.fillStyle=gradient;ctx.shadowColor='#42baff';ctx.shadowBlur=10;ctx.beginPath();ctx.roundRect(left,y-thick/2,right-left,thick,2);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#ffffffcc';ctx.fillRect(left+3,y-thick/2+2,right-left-6,2);
 }
 const pulse=state==='playing'&&!audio.paused?Math.max(0,1-((now-chart.beat_phase+beat)%beat)/beat):0;
 ctx.shadowColor='#5cdeff';ctx.shadowBlur=16+10*pulse;ctx.fillStyle='#7ef0ff';ctx.fillRect(0,line-2,w,4);ctx.shadowBlur=0;ctx.fillStyle='#d8fcff';ctx.fillRect(0,line-1,w,1);ctx.fillStyle='#37aaff22';ctx.fillRect(0,line+2,w,12);
 for(let i=0;i<4;i++){const cx=x(i+.5,line);ctx.strokeStyle='#9addff';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(cx,line,20,7,0,0,Math.PI*2);ctx.stroke();const age=(stamp-flashes[i])/350;if(age>=0&&age<1){ctx.strokeStyle='#c8faff'+Math.round((1-age)*255).toString(16).padStart(2,'0');ctx.beginPath();ctx.ellipse(cx,line,20+age*35,7+age*16,0,0,Math.PI*2);ctx.stroke()}}
 particles=particles.filter(p=>p.age<.45);for(const p of particles){p.age+=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=240*dt;ctx.globalAlpha=1-p.age/.45;ctx.fillStyle='#d1f5ff';ctx.fillRect(x(p.lane+.5,line)+p.x,line+p.y,3,3)}ctx.globalAlpha=1;
 if(stamp>judgeUntil)$('judge').textContent='';$('progress').style.width=Math.min(100,now/duration*100)+'%';$('time').textContent=clock(now)+' / '+clock(duration);requestAnimationFrame(frame)
}

reset();setState('select');frame();window.rhythmDebug={getState:()=>({running:state==='playing',state,score,combo,maxCombo,judged,time:audio.currentTime,notes,counts,emptyPresses,totalNotes:notes.length}),hit,release};
